// Exercise the actual built standalone tools. Inputs stay in the local browser;
// the automatic reader's refusal is received from the owned HTTP handler.
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {readFile,mkdir,writeFile} from 'node:fs/promises';
const r=createRequire(process.env.SDS_BROWSER_MODULES+'/package.json');
const origin=process.env.SDS_PREVIEW_ORIGIN||'http://127.0.0.1:31861',out=process.env.SDS_TOOLS_OUT||'/tmp/sds-tool-actions';await mkdir(out,{recursive:true});
const b=await r('puppeteer-core').launch({executablePath:'/usr/local/bin/google-chrome',headless:true,args:['--no-sandbox']});
const axe=await readFile(r.resolve('axe-core/axe.min.js'),'utf8'),report={views:[],actions:[],expectedRequests:[{path:'/api/tools/llms-txt',status:400,reason:'refuse loopback target'}]};
async function shot(p,name,width,theme){await p.addScriptTag({content:axe});const a=await p.evaluate(async()=>{const r=await axe.run(document,{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21a','wcag21aa']}});return {axe:r.violations.map(v=>({id:v.id,nodes:v.nodes.map(n=>({target:n.target,summary:n.failureSummary}))})),width:innerWidth,scrollWidth:document.documentElement.scrollWidth};});const screenshot=name+'-'+width+'-'+theme+'.jpg';await p.screenshot({path:out+'/'+screenshot,fullPage:true,type:'jpeg',quality:72});report.views.push({name,width,theme,screenshot,...a});await writeFile(out+'/report.json',JSON.stringify(report,null,2));}
async function copy(p,button,output){await p.bringToFront();await p.locator(button).click();await p.waitForFunction(s=>document.querySelector(s).textContent.startsWith('Copied'),{},button);assert.equal(await p.evaluate(()=>navigator.clipboard.readText()),await p.$eval(output,e=>e.textContent));}
try{for(const width of [390,768,1440])for(const theme of ['drafting','dark']){
 const c=await b.createBrowserContext();await c.overridePermissions(origin,['clipboard-read','clipboard-write','clipboard-sanitized-write']);const p=await c.newPage();await p.setViewport({width,height:900});await p.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);await p.evaluateOnNewDocument(t=>localStorage.setItem('sdd-theme',t),theme);
 const go=async name=>p.goto(origin+'/tools/'+name+'.html',{waitUntil:'networkidle2'});
 await go('schema-generator');await p.locator('#o_name').fill('Synthetic Workshop');await p.locator('#o_url').fill('https://example.com');assert.ok((await p.$eval('#output',e=>e.textContent)).includes('Synthetic Workshop'));await copy(p,'#copyBtn','#output');await p.focus('#tab-org');await p.keyboard.press('ArrowRight');assert.equal(await p.$eval('#tab-faq',e=>e.getAttribute('aria-selected')),'true');await p.locator('.fq').fill('How does booking work?');await p.locator('.fa').fill('Choose an appointment and confirm the requested time.');await p.locator('#addFaq').click();assert.equal(await p.$$eval('.faqRow',e=>e.length),4);await copy(p,'#copyBtn','#output');await shot(p,'schema-faq-generated',width,theme);
 await go('schema-validator');await p.locator('#run').click();assert.ok((await p.$eval('#results',e=>e.textContent)).includes('Paste'));await p.locator('#src').fill('{invalid');await p.locator('#run').click();assert.ok((await p.$eval('#results',e=>e.textContent)).includes('Invalid JSON'));await shot(p,'schema-invalid-json',width,theme);await p.locator('#src').fill(JSON.stringify({'@context':'https://schema.org','@type':'Organization',name:'Synthetic Workshop',url:'https://example.com',description:'Synthetic workshop booking information.'}));await p.locator('#run').click();assert.ok((await p.$eval('#results',e=>e.textContent)).includes('Valid JSON syntax'));await shot(p,'schema-valid-json',width,theme);
 await go('sitemap-generator');await p.locator('#urls').fill('https://example.com/\nhttps://example.com/about?a=1&b=2');await p.locator('#run').click();const xml=await p.$eval('#output',e=>e.textContent);assert.ok(xml.includes('&amp;'));assert.equal(await p.evaluate(s=>new DOMParser().parseFromString(s,'application/xml').querySelector('parsererror')===null,xml),true);await copy(p,'#copyBtn','#output');await shot(p,'sitemap-generated',width,theme);
 await go('llms-txt-generator');await p.locator('#name').fill('Synthetic Workshop');await p.locator('#summary').fill('Read the workshop booking information.');await p.locator('#addSec').click();await copy(p,'#copyBtn','#output');await shot(p,'llms-generated',width,theme);await p.locator('#autoUrl').fill('http://127.0.0.1/');await p.locator('#autoBtn').click();await p.waitForFunction(()=>document.querySelector('#autoStatus').textContent.includes("Couldn't read"));await shot(p,'llms-refuses-private-target',width,theme);
 await go('meta-tag-generator');await p.locator('#title').fill('Synthetic Workshop: book an appointment');await p.locator('#desc').fill('Read the workshop information and choose an appointment.');await p.locator('#url').fill('https://example.com');await copy(p,'#copyBtn','#output');await shot(p,'meta-tags-generated',width,theme);
 await go('ai-crawler-checker');await p.locator('#run').click();await p.locator('#rt').fill('User-agent: *\nAllow: /\n\nUser-agent: GPTBot\nDisallow: /');await p.locator('#run').click();assert.ok((await p.$eval('#results',e=>e.textContent)).includes('Blocked'));await copy(p,'#copyGen','#gen');await shot(p,'crawler-rules-checked',width,theme);
 report.actions.push({width,theme,tools:6,clipboard:true,schemaKeyboardTabs:true,privateTargetRefused:true});await c.close();console.log('TOOLS',width,theme,'passed');
}}finally{await b.close();await writeFile(out+'/report.json',JSON.stringify(report,null,2));}
